#pragma once
#include "ChessBoard.h"

#include <cstdint>
#include <vector>

// The opening book compiled into the engine (book_data.h, generated by make_book.cpp): a sorted
// table of position keys with the moves strong players chose there and how often.

// from | to << 6 | promotion piece << 12, the same encoding the book tables and the search use
uint16_t PackMove(const Move& m);

struct BookChoice {
  Move move;
  int games = 0;  // how many of the source games played this move here
};

// Picks one of the book moves for this position at random, in proportion to how often each was
// played. Returns false if the position is not in the book.
bool BookPick(const ChessBoard& b, const std::vector<Move>& legal, BookChoice& out);

// Is `move` (packed) one of the book moves in this position?
bool BookHasMove(const ChessBoard& b, uint16_t move);

// Number of entries in the book, for tests and diagnostics.
unsigned BookSize();
